	gongMarshallInstances(stage, stage.Prints, &identifiersDecl, &initializerStatements, &pointersInitializesStatements)
	gongMarshallInstances(stage, stage.Roots, &identifiersDecl, &initializerStatements, &pointersInitializesStatements)
	gongMarshallInstances(stage, stage.RootSteps, &identifiersDecl, &initializerStatements, &pointersInitializesStatements)
	gongMarshallInstances(stage, stage.Scordaturas, &identifiersDecl, &initializerStatements, &pointersInitializesStatements)
	gongMarshallInstances(stage, stage.Sounds, &identifiersDecl, &initializerStatements, &pointersInitializesStatements)
	gongMarshallInstances(stage, stage.StaffDivides, &identifiersDecl, &initializerStatements, &pointersInitializesStatements)
	gongMarshallInstances(stage, stage.Sticks, &identifiersDecl, &initializerStatements, &pointersInitializesStatements)
